-- Carga de demonstração: usuários 203 (DELTA DEMO), 204 (jota) e 210 (jota22)
-- Objetivo: deixar mobile e web com dados bem populados para os três usuários.
--
-- O que faz:
--   1. completa o usuário 210 (2 imóveis, vínculos, hábitos, faturas, dispositivos);
--   2. move o dispositivo ESP32-SP-0159 do imóvel 159 (usuário 203) para o imóvel do 210;
--   3. completa hábitos, faturas e preferências do usuário 203;
--   4. completa o consumo de todos os dispositivos dos três usuários até hoje (02/11/2026);
--   5. adiciona alertas e recarrega silver e gold.
--
-- Ids novos usam a faixa 8000001 em diante (nenhuma tabela usa ids acima de 300 hoje).
-- Pode ser executado mais de uma vez: tudo usa ON CONFLICT DO NOTHING.
-- Execute numa transação única (ex.: psql -1 -f ou BEGIN/COMMIT).


-- Endereços antigos sem coordenadas (necessário para tb_address.latitude/longitude NOT NULL).
UPDATE tb_address SET latitude = -23.550520, longitude = -46.633308
 WHERE id IN (163, 221) AND (latitude IS NULL OR longitude IS NULL);


-- ENDEREÇOS DO USUÁRIO 210
ON CONFLICT DO NOTHING;

-- IMÓVEIS DO USUÁRIO 210
ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

-- DISPOSITIVOS
-- O ESP32-SP-0159 estava no imóvel 159 (usuário 203); o consumo dele é do usuário 210.
UPDATE tb_device SET property_id = 8000001
 WHERE device_id = 'ESP32-SP-0159' AND property_id = 159;

ON CONFLICT DO NOTHING;

-- HÁBITOS dos usuários 203 e 210 (o 204 já tem 21)
ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

-- FATURAS: maio a julho para os três usuários; agosto e outubro para o 210
ON CONFLICT DO NOTHING;

-- CONSUMO NA STAGE: continua o histórico de cada dispositivo até hoje (2 janelas por dia)
-- A janela da tarde de hoje vai até 15:30 para não gerar consumo no futuro.
ON CONFLICT (mongo_id) DO NOTHING;

-- PREFERÊNCIAS dos usuários 203 e 210 (o 204 já tem)
SELECT v.mongo_id, v.user_id, v.target, v.notif, v.q_start, v.q_end, v.dark
  FROM (VALUES
        ('dmpref203', 203, 450, TRUE, '22:00', '07:00', FALSE),
        ('dmpref210', 210, 280, TRUE, '23:00', '06:30', TRUE)
       ) AS v(mongo_id, user_id, target, notif, q_start, q_end, dark)
 WHERE NOT EXISTS (SELECT 1 FROM stage.user_preferences p WHERE p.user_id = v.user_id)
ON CONFLICT (mongo_id) DO NOTHING;

-- ALERTAS (alguns ainda abertos, sem resolved_at)
ON CONFLICT (mongo_id) DO NOTHING;

-- RECARGA das camadas silver e gold (mesma cadeia usada pelo bi_etl.py)
CALL silver.sp_load();
CALL gold.sp_load();
